package com.ptms.service; import com.ptms.domain.PersonType; import org.junit.jupiter.api.Test; import java.time.*; import static org.assertj.core.api.Assertions.*;
class ParkingDurationServiceTest{@Test void weekdayPass(){int h=new ParkingDurationService().requiredTicketHours(PersonType.EMPLOYEE,true,LocalDate.of(2026,9,14),LocalTime.of(8,0),LocalTime.of(17,0),0);assertThat(h).isEqualTo(5);}@Test void weekendPass(){int h=new ParkingDurationService().requiredTicketHours(PersonType.EMPLOYEE,true,LocalDate.of(2026,9,19),LocalTime.of(8,0),LocalTime.of(14,0),0);assertThat(h).isEqualTo(2);}}
